#!/usr/bin/env Rscript
repo_root<-normalizePath(if(length(commandArgs(TRUE)))commandArgs(TRUE)[[1]] else ".",winslash="/")
source(file.path(repo_root,"methodology/tests/fixtures.R"))
results<-list();check<-function(name,value){ok<-tryCatch(isTRUE(force(value)),error=function(e)FALSE);results[[name]]<<-ok;cat(if(ok)"PASS" else "FAIL",name,"\n")}
root<-tempfile("livefix-");dir.create(root)
p<-list(id="ledger",keys=list("id"),exact_fields=list("state"),numeric_fields=list("amount"),absolute_tolerance=0,relative_tolerance=0,field_nullability=list(amount=TRUE),numeric_missingness=list(amount=list(flag_field="state",missing_value="missing",present_value="present",missing_token="")))
s3<-list(methodology=list(checkpoints=list(p),operational=list(checkpoint_output_rules=list(list(checkpoint_id="ledger",field="amount",nullable=TRUE)))))
check("D22 explicit nullable contract accepted",m_pass(m_checkpoint_contract(s3)))
bad<-s3;bad$methodology$operational$checkpoint_output_rules[[1]]$nullable<-FALSE
check("D22 output versus checkpoint conflict rejected",!m_pass(m_checkpoint_contract(bad)))
bad<-s3;bad$methodology$checkpoints[[1]]$numeric_missingness<-NULL
check("D22 nullable finite-only contract rejected at Design",!m_pass(m_checkpoint_contract(bad)))
bad<-s3;bad$methodology$checkpoints[[1]]$field_nullability<-NULL
check("D22 undeclared nullability rejected",!m_pass(m_checkpoint_contract(bad)))
bad<-s3;bad$methodology$checkpoints[[1]]$numeric_missingness$amount$flag_field<-"uncompared"
check("D22 unpaired missingness flag rejected",!m_pass(m_checkpoint_contract(bad)))
a<-data.frame(id=c("A","B","C","D","E","F","G","H"),state=c(rep("present",6),"missing","present"),amount=c("9","10","11","20","10","0","","30"))
check("D22 eight-row missing G compares by key",m_compare(a,a[8:1,],p))
b<-a;b$state[7]<-"present";b$amount[7]<-"0";check("D22 missing versus zero rejected",!m_compare(a,b,p))
b<-a;b$amount[1]<-"Inf";check("D22 unexpected infinity rejected",!m_compare(a,b,p))
b<-a;b$amount[1]<-"NaN";check("D22 unexpected NaN rejected",!m_compare(a,b,p))
b<-a;b$amount[7]<-"null";check("D22 wrong missing token rejected",!m_compare(a,b,p))
b<-a;b$id[7]<-"NEW";check("D22 missing row identity mismatch rejected",!m_compare(a,b,p))
pstrict<-p;pstrict$numeric_missingness<-NULL;pstrict$field_nullability<-list(amount=FALSE)
check("D22 legacy finite-only behavior retained",!m_compare(a,a,pstrict))
check("D22 all-missing rows supported only with policy",m_compare(a[7,,drop=FALSE],a[7,,drop=FALSE],p))
# Immutable candidate and transitive operations closure.
t_file(root,"candidate.json",'{"version":"candidate-1"}')
frozen<-m_freeze_file("candidate.json",root)
t_file(root,"candidate.json",'{"version":"locked-2"}')
check("D20 snapshot survives candidate rewrite",m_ref_ok(frozen,root))
check("D20 snapshot is idempotent",identical(m_freeze_file(frozen$path,root),m_freeze_file(frozen$path,root)))
now<-format(Sys.time(),"%Y-%m-%dT%H:%M:%SZ",tz="UTC")
t_write(root,"artifacts/procedure/checks/start-begin.json",list(step="start",phase="begin",result="PASS",checked_at_utc=now))
state<-list(run_id="SYNTHETIC-LIVEFIX",current_step="start",current_authorization=m_file_ref("artifacts/procedure/checks/start-begin.json",root))
if(!file.exists(file.path(root,"artifacts/stage1_decision.json")))t_write(root,"artifacts/stage1_decision.json",list(stage=1,status="LOCKED",note="synthetic receipt for review coverage"))
t_stage_records(root)
t_write(root,"artifacts/procedure/run_state.json",state);t_operations(root,"start")
opath<-"artifacts/operations/start.json";o<-m_read(file.path(root,opath));packetpath<-o$sends[[1]]$packet$path
packet<-m_read(file.path(root,packetpath));packet$design_candidate<-m_file_ref("candidate.json",root);t_write(root,packetpath,packet)
o$sends[[1]]$packet<-m_file_ref(packetpath,root)
capath<-o$sends[[1]]$capture$path;cap<-m_read(file.path(root,capath));cap$packet<-o$sends[[1]]$packet;t_write(root,capath,cap);o$sends[[1]]$capture<-m_file_ref(capath,root);t_write(root,opath,o)
check("D20 current nested packet accepted",m_pass(m_operations(root,state,"start")))
t_file(root,"candidate.json",'{"version":"rewritten-after-send"}')
check("D20 rewritten nested reference refused at completion",!m_pass(m_operations(root,state,"start")))
packet$design_candidate<-frozen;t_write(root,packetpath,packet);o$sends[[1]]$packet<-m_file_ref(packetpath,root);cap$packet<-o$sends[[1]]$packet;t_write(root,capath,cap);o$sends[[1]]$capture<-m_file_ref(capath,root);t_write(root,opath,o)
check("D20 immutable candidate references accepted",m_pass(m_operations(root,state,"start")))
# D07 (capture method attestation) removed with capture match, P01 cut 2026-10-31; stale/foreign captures are caught by review coverage.
check("D03 Windows path canonicalized",identical(m_relative_path("C:\\run\\artifacts\\begin.json","C:/run"),"artifacts/begin.json"))
check("D03 traversal rejected",inherits(try(m_relative_path("C:/run/../outside","C:/run"),silent=TRUE),"try-error"))
check("D03 outside prefix rejected",inherits(try(m_relative_path("C:/runner/file","C:/run"),silent=TRUE),"try-error"))
# File-only source still needs current fidelity evidence.
report<-t_file(root,"source-check.txt","SYNTHETIC CP00 fidelity evidence")
t_write(root,"source.json",list(status="PASS",source_kind="file",sql_extraction_used=FALSE,fidelity_check=list(status="PASS",report=report)))
s<-list(methodology=list(operational=list(source_contract=list(kind="file"))))
e<-list(sql_source_gate="NOT_APPLICABLE",evidence_receipts=list(source=m_file_ref("source.json",root)))
check("SQL N/A with file fidelity accepted",m_pass(m_source(s,e,root)))
e$sql_source_gate<-"PASS";check("SQL false PASS on file-only input rejected",!m_pass(m_source(s,e,root)))
e$sql_source_gate<-"NOT_APPLICABLE";s$methodology$operational$source_contract$kind<-"sql";check("SQL N/A rejected for SQL source",!m_pass(m_source(s,e,root)))
s$methodology$operational$source_contract$kind<-"file";t_file(root,"source-check.txt","changed");check("N/A does not bypass fidelity hashes",!m_pass(m_source(s,e,root)))
# Actual child inheritance, failures, and parent restoration; works in Windows CI too.
child<-file.path(root,"child.R");out<-file.path(root,"child.txt")
writeLines('writeLines(Sys.getenv("WORKFLOW_TEST_SENTINEL"),commandArgs(TRUE)[[1]])',child)
old<-Sys.getenv("WORKFLOW_TEST_SENTINEL",unset=NA_character_)
status<-m_run_child(child,out,c(WORKFLOW_TEST_SENTINEL="expected child value"),file.path(root,"child.log"))
check("D27 actual child inherits environment",status==0L&&identical(readLines(out),"expected child value"))
check("D27 parent environment restored",identical(Sys.getenv("WORKFLOW_TEST_SENTINEL",unset=NA_character_),old))
writeLines('stop("intentional failure")',child)
status<-suppressWarnings(m_run_child(child,environment=c(WORKFLOW_TEST_SENTINEL="temporary"),log=file.path(root,"failed-child.log")))
check("D27 child failure retained",status!=0L&&file.exists(file.path(root,"failed-child.log")))
check("D27 parent restored after failure",identical(Sys.getenv("WORKFLOW_TEST_SENTINEL",unset=NA_character_),old))
# Exercise the actual restore wrapper without installing packages.
restore<-file.path(root,"restore-example.R")
writeLines('a<-commandArgs(TRUE);stopifnot(dir.exists(a[[2]]));writeLines("reviewed synthetic restore executed",file.path(a[[1]],"restore-ran.txt"))',restore)
status<-system2(file.path(R.home("bin"),"Rscript"),c(shQuote(file.path(repo_root,"tools/run_restore.R")),shQuote(root),shQuote(restore),shQuote(file.path(root,"fresh-library")),shQuote(file.path(root,"restore-attempt"))),stdout=file.path(root,"wrapper.log"),stderr=file.path(root,"wrapper.log"))
check("D27 wrapper probes fresh child library",status==0L && file.exists(file.path(root,"restore-attempt/after-environment.txt")) && file.exists(file.path(root,"restore-ran.txt")))
if(status!=0L)cat(readLines(file.path(root,"wrapper.log")),sep="\n")
cat(sum(unlist(results)),"/",length(results),"live-finding checks passed\n")
if(!all(unlist(results)))quit(status=1)
